import{_ as s,o as t,a as l,b as n}from"./app.C41L12d5.js";const p="/ascendc.github.io/assets/mxmmad_demo_a5.DGRUxhQX.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"Mmad计算","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/mmad_compute"},{"text":"MmadMx","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/MmadMx"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/MmadMx.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/MmadMx.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":3,"title":"不传入bias的原型","slug":"不传入bias的原型","link":"#不传入bias的原型"},{"level":3,"title":"传入bias的原型","slug":"传入bias的原型","link":"#传入bias的原型"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788166713000}'),d={name:"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/MmadMx.md"};function e(c,a,i,r,o,m){return t(),l("div",null,[...a[0]||(a[0]=[n('<div><article class="markdown-body"><h1>MmadMx<span id="ZH-CN_TOPIC_000000253823118102"></span></h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><h3 id="不传入bias的原型">不传入bias的原型<a class="header-anchor" href="#不传入bias的原型">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h3 id="传入bias的原型">传入bias的原型<a class="header-anchor" href="#传入bias的原型">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_mm_intf.h&quot;</code>。</p><p>MmadMx（全称Microscaling Mmad）为带有量化系数的矩阵乘法，即左矩阵和右矩阵均有对应的量化系数矩阵，左量化系数矩阵scaleA和右量化系数矩阵scaleB。MmadMx场景中，左量化系数矩阵与左矩阵乘积，右量化系数矩阵与右矩阵乘积，对两个乘积的结果做矩阵乘法。</p><p>MmadMx的计算公式为：C=(scaleA⊗A)*(scaleB⊗B)+Bias，“⊗”表示广播乘法，左/右矩阵与左/右量化系数矩阵做乘积时，K方向上每32个元素共享一个量化因子，如<a href="#zh_cn_topic_mmadmx_section2_figure1">图1</a>所示（其中以AB矩阵均为fp4x2_e2m1_t数据类型为例）。</p><ul><li>A、scaleA、B、scaleB为源操作数。A为左矩阵，形状为[M,K]；scaleA为左量化系数矩阵，形状为[M,K/32]；B为右矩阵，形状为[K,N]；scaleB为右量化系数矩阵，形状为[K/32,N]。</li><li>C为目的操作数，存放矩阵乘结果的矩阵，形状为[M,N]。</li><li>Bias为矩阵乘偏置，形状为[1,N]。对(scaleA⊗A)*(scaleB⊗B)结果矩阵的每一行都采用该Bias进行偏置。</li></ul><p><strong>图1</strong> MmadMx接口矩阵乘分形示意图<a id="zh_cn_topic_mmadmx_section2_figure1"></a><img src="'+p+`" alt="MmadMx接口矩阵乘分形示意图" title="MmadMx接口矩阵乘分形示意图"></p><p><strong>表1</strong> 矩阵计算矩阵A、B、C解释说明</p><table><thead><tr><th>矩阵计算逻辑</th><th>矩阵计算物理位置</th><th>维度</th><th>输入/输出数据格式</th><th>数据类型</th></tr></thead><tbody><tr><td>A</td><td>L0A Buffer</td><td>M x K</td><td>[Nz]</td><td rowspan="5"><a href="#zh_cn_topic_mmadmx_section_datatype">数据类型</a></td></tr><tr><td>scaleA</td><td>L0A_MX Buffer</td><td>M x K/32</td><td>[大Z小z]小z shape为（2，16）</td></tr><tr><td>B</td><td>L0B Buffer</td><td>K x N</td><td>[Zn]</td></tr><tr><td>scaleB</td><td>L0B_MX Buffer</td><td>K/32 x N</td><td>[大N小n]小n shape为（2，16）</td></tr><tr><td>C</td><td>L0C Buffer</td><td>M x N，可支持使用偏置矩阵Bias进行初始化，维度为1 x N</td><td>[Nz]</td></tr></tbody></table><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>不传入bias</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">S</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">MmadMx</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">fm</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">S</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">filter</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">MmadParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">)</span>
</code></pre></div></li><li><p>传入bias</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">S</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">V</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">MmadMx</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">fm</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">S</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">filter</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">V</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">bias</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">MmadParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，结果矩阵C，类型为LocalTensor，支持的物理存储位置为L0C Buffer（TPosition:CO1）。<br>LocalTensor的起始地址需要按照1024字节对齐。</td></tr><tr><td>fm</td><td>输入</td><td>源操作数，左矩阵A，类型为LocalTensor，支持的物理存储位置为L0A Buffer（TPosition:A2）。<br>左矩阵A对应的scale矩阵起始地址为：A矩阵起始对应地址/16。<br>对于fp4场景LocalTensor的起始地址需要按照512字节对齐。对于fp8场景LocalTensor的起始地址需要按照1024字节对齐。</td></tr><tr><td>filter</td><td>输入</td><td>源操作数，右矩阵B，类型为LocalTensor，支持的物理存储位置为L0B Buffer（TPosition:B2）。<br>右矩阵B对应的scale矩阵起始地址为：B矩阵起始对应地址/16。<br>对于fp4场景LocalTensor的起始地址需要按照512字节对齐。对于fp8场景LocalTensor的起始地址需要按照1024字节对齐。</td></tr><tr><td>bias</td><td>输入</td><td>源操作数，Bias矩阵，类型为LocalTensor，支持的物理存储位置为BT Buffer（TPosition:C2）。<br>LocalTensor的起始地址需要按照64字节对齐。</td></tr><tr><td>mmadParams</td><td>输入</td><td>矩阵乘相关参数。<br>该参数类型的具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_mm.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。<br>MmadParams参数说明请参考<a href="Mmad.html#zh_cn_topic_mmad_section4_table4">MmadParams结构体内参数说明</a>。</td></tr></tbody></table><h2 id="数据类型">数据类型<a id="zh_cn_topic_mmadmx_section_datatype"></a><a class="header-anchor" href="#数据类型">​</a></h2><p><strong>表3</strong> MmadMx接口左矩阵、右矩阵、Scale矩阵、Bias矩阵、结果矩阵支持的精度类型组合（Ascend 950PR/Ascend 950DT）</p><table><thead><tr><th>左矩阵fm</th><th>右矩阵filter</th><th>Scale矩阵</th><th>偏置Bias</th><th>结果矩阵dst</th></tr></thead><tbody><tr><td>fp4x2_e1m2_t</td><td>fp4x2_e1m2_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr><tr><td>fp4x2_e2m1_t</td><td>fp4x2_e1m2_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr><tr><td>fp4x2_e1m2_t</td><td>fp4x2_e2m1_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr><tr><td>fp4x2_e2m1_t</td><td>fp4x2_e2m1_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr><tr><td>fp8_e4m3fn_t</td><td>fp8_e4m3fn_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr><tr><td>fp8_e4m3fn_t</td><td>fp8_e5m2_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr><tr><td>fp8_e5m2_t</td><td>fp8_e4m3fn_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr><tr><td>fp8_e5m2_t</td><td>fp8_e5m2_t</td><td>fp8_e8m0_t</td><td>float</td><td>float</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>不同矩阵对于存储位置的约束： <ul><li>结果矩阵C只支持位于物理存储位置为L0C Buffer（TPosition:CO1），大小256KB。</li><li>左矩阵A只支持位于物理存储位置为L0A Buffer（TPosition:A2），大小64KB。</li><li>右矩阵B只支持位于物理存储位置为L0B Buffer（TPosition:B2），大小64KB。</li><li>Bias矩阵只支持位于物理存储位置为BT Buffer（TPosition:C2），大小4KB。</li></ul></li><li>地址约束说明请参考表2。</li><li>当M、K、N中的任意一个值为0时，表示指令不会执行，该接口将被视为NOP（空操作）。</li><li>K需要是64的倍数。</li><li>对于fp4场景A/B矩阵的起始地址需要按照512字节对齐，对于fp8场景A/B矩阵的起始地址需要按照1024字节对齐。</li><li>左矩阵A/B对应的scale矩阵起始地址为：A/B矩阵起始对应地址/16。</li><li>其他特殊场景约束可参考<a href="Mmad.html#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">Mmad接口约束说明</a>。</li><li>边界值计算结果请见<a href="../../../../appendix/mmad_mx_interface_boundary_value_summary.html">MmadMx接口边界值汇总</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>完整使用样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_mxfp4_basic_api_high_performance">MmadMx最佳实践</a>。</p></article></div>`,1)])])}const f=s(d,[["render",e]]);export{h as __pageData,f as default};
